using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Options with a default resolver — resolves any type automatically.
var webOptions = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1. GetTypeInfo<T>() — returns JsonTypeInfo<T> directly, no cast needed.
JsonTypeInfo<Person> personInfo = webOptions.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> → Type = {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Console.WriteLine($"Serialized: {json}");

// 2. TryGetTypeInfo<T>() — probe without throwing.
//    With the web defaults resolver every type resolves, so Person succeeds:
if (webOptions.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? info))
    Console.WriteLine($"TryGetTypeInfo<Person> succeeded → {info!.Type.Name}");
else
    Console.WriteLine("TryGetTypeInfo<Person> returned false");

// Now use options whose resolver only knows about Person (via source-gen).
// Widget is NOT in that set, so TryGetTypeInfo<Widget> returns false
// instead of throwing.
var restrictedOptions = new JsonSerializerOptions();
restrictedOptions.TypeInfoResolverChain.Add(PersonContext.Default);

if (restrictedOptions.TryGetTypeInfo<Widget>(out JsonTypeInfo<Widget>? widgetInfo))
    Console.WriteLine($"TryGetTypeInfo<Widget> succeeded → {widgetInfo!.Type.Name}");
else
    Console.WriteLine("TryGetTypeInfo<Widget> returned false — metadata not available");

// --- Types ---------------------------------------------------------------

public record Person(string Name, int Age);
public record Widget(int Id, string Label);

[JsonSerializable(typeof(Person))]
public partial class PersonContext : JsonSerializerContext;

