 // Widget is NOT in that set, so TryGetTypeInfo<Widget> returns false
 // instead of throwing.
 var restrictedOptions = new JsonSerializerOptions();
 restrictedOptions.TypeInfoResolverChain.Add(PersonContext.Default);

 if (restrictedOptions.TryGetTypeInfo<Widget>(out JsonTypeInfo<Widget>? widgetInfo))
     Console.WriteLine($"TryGetTypeInfo<Widget> succeeded → {widgetInfo!.Type.Name}");
 else
     Console.WriteLine("TryGetTypeInfo<Widget> returned false — metadata not available");

